/* Shared classroom controls: user-directed motion and one idea per presentation step. */
(()=>{
const $=s=>document.querySelector(s),safe=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const bar=document.createElement('div');bar.id='projectionTools';bar.hidden=true;bar.setAttribute('aria-label','Herramientas para proyectar');bar.innerHTML='<strong>Para el aula</strong><button class="ghost-btn" id="projectionSize" aria-pressed="false">Texto más grande</button><button class="ghost-btn" id="projectionFull">Pantalla completa</button><span id="projectionStatus" role="status">Esc para salir del modo proyector</span>';$('.topbar').after(bar);
let ownedFullscreen=false;
function sync(){const active=document.body.classList.contains('projector-mode');bar.hidden=!active;if(!active){document.body.classList.remove('projection-large');$('#projectionSize').setAttribute('aria-pressed','false');$('#projectionSize').textContent='Texto más grande';if(ownedFullscreen&&document.fullscreenElement)document.exitFullscreen?.().catch(()=>{});ownedFullscreen=false;}if($('#comicProject'))$('#comicProject').textContent=active?'Salir del proyector':'Modo proyector';}
window.addEventListener('atlas-projector-change',sync);
$('#projectionSize').onclick=()=>{const large=document.body.classList.toggle('projection-large');$('#projectionSize').setAttribute('aria-pressed',String(large));$('#projectionSize').textContent=large?'Texto normal':'Texto más grande';};
$('#projectionFull').onclick=async()=>{try{if(document.fullscreenElement){await document.exitFullscreen();ownedFullscreen=false;}else if(document.documentElement.requestFullscreen){await document.documentElement.requestFullscreen();ownedFullscreen=true;}else $('#projectionStatus').textContent='Usa la opción de pantalla completa de tu navegador.';}catch{$('#projectionStatus').textContent='El navegador no permitió pantalla completa. Puedes seguir proyectando.';}};
document.addEventListener('fullscreenchange',()=>{$('#projectionFull').textContent=document.fullscreenElement?'Salir de pantalla completa':'Pantalla completa';});
document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]')||e.target.matches('input,textarea,select,[contenteditable="true"]'))return;if(e.key==='Escape'&&document.body.classList.contains('projector-mode'))$('#projectorBtn').click();if(location.hash.startsWith('#historietas')&&!e.target.matches('button,a,summary')&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();$(e.key==='ArrowLeft'?'#comicPrev':'#comicNext').click();}});
window.AtlasProjection={install(t){if(t.id==='mesoamerica')return;const b=document.createElement('button');b.className='btn btn-secondary';b.id='presentRoute';b.textContent='Presentar paso a paso';$('#ruta .actions').prepend(b);b.onclick=()=>present(t,b);}};
function present(t,opener){const slides=[{title:t.question,text:t.objective},...t.classroom.map((text,i)=>({title:`${t.title} · idea ${i+1}`,text})),...t.dates.map(([date,text])=>({title:date,text})),{title:'Pausa para pensar',text:t.curiosity},...t.activity.map((text,i)=>({title:`Actividad · paso ${i+1}`,text})),{title:'¿Qué aprendimos?',text:t.assessment}];let index=0;const dialog=document.createElement('dialog');dialog.className='lesson-presenter';dialog.id='routePresenter';dialog.setAttribute('aria-label','Presentación de '+t.title);dialog.innerHTML='<div class="lesson-toolbar"><span>'+safe(t.title)+'</span><button class="ghost-btn" data-close>Cerrar presentación</button></div><div class="lesson-stage" tabindex="-1"></div><div class="lesson-bottom"><button class="ghost-btn" data-prev>Anterior</button><span data-count aria-live="polite"></span><button class="btn btn-primary" data-next>Siguiente</button></div>';document.body.append(dialog);
const stage=dialog.querySelector('.lesson-stage');function draw(){const s=slides[index];stage.innerHTML=`<p class="eyebrow">ATLAS DEL TIEMPO · PARA CONVERSAR EN CLASE</p><h2>${safe(s.title)}</h2><p class="lesson-big">${safe(s.text)}</p>`;dialog.querySelector('[data-count]').textContent=`${index+1} de ${slides.length}`;dialog.querySelector('[data-prev]').disabled=index===0;dialog.querySelector('[data-next]').textContent=index===slides.length-1?'Terminar':'Siguiente';stage.scrollTop=0;stage.focus();}function close(){dialog.close();}dialog.querySelector('[data-close]').onclick=close;dialog.querySelector('[data-prev]').onclick=()=>{if(index>0){index--;draw();}};dialog.querySelector('[data-next]').onclick=()=>{if(index<slides.length-1){index++;draw();}else close();};dialog.addEventListener('keydown',e=>{if(e.target.matches('button'))return;if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();dialog.querySelector(e.key==='ArrowRight'?'[data-next]':'[data-prev]').click();}});const changed=()=>close();window.addEventListener('hashchange',changed);dialog.addEventListener('close',()=>{window.removeEventListener('hashchange',changed);dialog.remove();document.body.classList.remove('presenting');if(opener.isConnected)opener.focus();},{once:true});document.body.classList.add('presenting');dialog.showModal();draw();}
})();
